import{WIDTH,HEIGHT,npcs,terminal,quests,createState,nearestTarget,recordMeeting,inspect}from'./engine.js';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),keys=new Set();let state=createState(),target=null,currentNpc=null,aiReady=false,busy=false,last=performance.now();
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function text(t,x,y,c='#e8e2d5',size=12,align='left'){ctx.fillStyle=c;ctx.font=`${size}px ui-monospace,monospace`;ctx.textAlign=align;ctx.fillText(t,x,y)}
function drawPerson(x,y,color,selected=false){if(selected){ctx.strokeStyle='#f0bb46';ctx.lineWidth=2;ctx.strokeRect(x-13,y-24,26,40)}rect(x-8,y-13,16,19,color);rect(x-6,y-21,12,9,'#d2a37f');rect(x-8,y+6,6,9,'#263342');rect(x+2,y+6,6,9,'#263342')}
function drawWorld(){rect(0,0,WIDTH,HEIGHT,'#50635a');for(let y=0;y<HEIGHT;y+=32)for(let x=0;x<WIDTH;x+=32)if((x/32+y/32)%2===0)rect(x,y,32,32,'#53695e');rect(38,35,310,222,'#334250');rect(52,49,282,194,'#687887');rect(68,66,250,160,'#25313c');text('维修车间',80,91,'#f0bb46',15);rect(392,34,334,242,'#3b4653');rect(407,49,304,213,'#71808b');rect(424,66,270,179,'#252f39');text('研发试验区',438,91,'#75d3d0',15);rect(35,323,272,154,'#474351');rect(49,337,244,126,'#232a37');text('旧宿舍',64,361,'#d7c5e8',15);rect(338,347,388,130,'#5a5143');rect(352,361,360,102,'#282d32');text('食堂与公共区',368,385,'#f0c98c',15);rect(334,278,64,199,'#827863');rect(0,284,768,28,'#81765f');for(let x=6;x<768;x+=48)rect(x,296,24,3,'#b4a98e');rect(terminal.x,terminal.y,terminal.w,terminal.h,'#151b22');rect(terminal.x+8,terminal.y+8,56,22,'#304253');rect(terminal.x+13,terminal.y+13,6,6,state.quest===1?'#e56f62':'#75d3d0');text('07',terminal.x+53,terminal.y+24,'#aebbc6',10,'right');npcs.forEach(n=>{drawPerson(n.x,n.y,n.color,target?.id===n.id);text(n.name,n.x,n.y-31,'#f5f0e7',11,'center')});drawPerson(state.player.x,state.player.y,'#d7aa3e');text('周予安',state.player.x,state.player.y-31,'#f0bb46',11,'center');ctx.strokeStyle='#1118';ctx.lineWidth=5;ctx.strokeRect(2,2,WIDTH-4,HEIGHT-4)}
function blocked(x,y){if(x<20||x>WIDTH-20||y<28||y>HEIGHT-20)return true;const buildings=[{x:38,y:35,w:310,h:222},{x:392,y:34,w:334,h:242},{x:35,y:323,w:272,h:154},{x:338,y:347,w:388,h:130}];return buildings.some(b=>x>b.x-10&&x<b.x+b.w+10&&y>b.y-10&&y<b.y+b.h+10)}
function update(dt){if(!$('#dialogue').hidden)return;let dx=0,dy=0;if(keys.has('arrowleft')||keys.has('a'))dx--;if(keys.has('arrowright')||keys.has('d'))dx++;if(keys.has('arrowup')||keys.has('w'))dy--;if(keys.has('arrowdown')||keys.has('s'))dy++;if(dx||dy){const len=Math.hypot(dx,dy),speed=145*dt;dx=dx/len*speed;dy=dy/len*speed;if(!blocked(state.player.x+dx,state.player.y))state.player.x+=dx;if(!blocked(state.player.x,state.player.y+dy))state.player.y+=dy;state.player.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up')}target=nearestTarget(state);$('#prompt').hidden=!target;$('#prompt').textContent=target?.type==='terminal'?'按 E 调查控制柜':'按 E 交谈'}
function frame(now){update(Math.min((now-last)/1000,.05));drawWorld();last=now;requestAnimationFrame(frame)}
function renderUI(){const q=quests[state.quest];$('#quest-title').textContent=q.title;$('#quest-copy').textContent=q.copy;$('#quest-progress').style.width=`${(state.quest+1)/quests.length*100}%`;$('#belonging').textContent=String(state.belonging).padStart(2,'0');$('#clues').textContent=String(state.clues).padStart(2,'0');$('#journal').innerHTML=state.notes.slice(0,3).map((n,i)=>`<div class="note ${i===0?'new':''}">${escape(n)}</div>`).join('')}
function notify(message){const e=$('#toast');e.textContent=message;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
function act(){target=nearestTarget(state);if(!target)return;if(target.type==='terminal'){if(inspect(state)){notify('获得线索：过温警告');renderUI()}else notify('目前没有需要调查的内容。');return}openDialogue(npcs.find(n=>n.id===target.id))}
function openDialogue(npc){currentNpc=npc;recordMeeting(state,npc.id);renderUI();$('#speaker').textContent=npc.name;$('#speaker-role').textContent=npc.role;$('#relation').textContent=`关系记忆 ${state.memories[npc.id]?.length||0} 条`;$('#portrait').style.setProperty('--portrait',npc.color);$('#portrait').style.setProperty('--shirt',npc.color);$('#speech').textContent=npc.intro;$('#suggestions').innerHTML=npc.suggestions.map(s=>`<button data-say="${escape(s)}">${escape(s)}</button>`).join('');$('#dialogue-status').textContent=aiReady?'DeepSeek 会依据角色记忆回应。':'本地剧情模式；配置 API 后可自由对话。';$('#dialogue').hidden=false;$('#message').focus()}
function closeDialogue(){$('#dialogue').hidden=true;currentNpc=null}
function localReply(npc,message){const replies={liang:'有问题就把记录拿出来，我们先停下来核对。做事要较真，说话也要给人留余地。',xu:'技术判断可以争，但记录必须完整。你看到的异常，我会安排复核。',zhou:'我知道你还把自己当过客。先和这里的人一起做完一件事，再决定要不要走。',he:'我没有答案。我只知道，真实的人比我们隔着海想象出来的样子复杂。'};return replies[npc.id]+(message.includes('留下')?' 留不留下，都别骗自己。':'')}
async function talk(message){if(!currentNpc||busy||!message.trim())return;busy=true;$('#dialogue-status').textContent=aiReady?'对方正在思考…':'本地剧情回应';let reply;try{if(aiReady){const payload={npc:currentNpc.id,message:message.trim(),quest:state.quest,met:state.met,memories:(state.memories[currentNpc.id]||[]).slice(-4)};const res=await fetch('/api/dialogue',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(45000)});const data=await res.json();if(!res.ok)throw new Error(data.error||'暂时无法回应');reply=data.reply}else reply=localReply(currentNpc,message);$('#speech').innerHTML=`<small>周予安：${escape(message)}</small><br><br>${escape(reply)}`;state.memories[currentNpc.id]??=[];state.memories[currentNpc.id].push(`我问：“${message}” ${currentNpc.name}回答：“${reply}”`);state.memories[currentNpc.id]=state.memories[currentNpc.id].slice(-6);state.notes.unshift(`与${currentNpc.name}交谈：${reply}`);$('#relation').textContent=`关系记忆 ${state.memories[currentNpc.id].length} 条`;renderUI();$('#dialogue-status').textContent=aiReady?'AI 回应完成。':'本地剧情模式。'}catch(e){$('#dialogue-status').textContent=e.name==='TimeoutError'?'回应超时，请再试一次。':e.message}finally{busy=false}}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','e'].includes(k))e.preventDefault();keys.add(k);if((k==='e'||k===' ')&&$('#dialogue').hidden)act();if(k==='escape'&&!$('#dialogue').hidden)closeDialogue()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));$('#close').onclick=closeDialogue;$('#dialogue').onclick=e=>{if(e.target===$('#dialogue'))closeDialogue()};$('#suggestions').onclick=e=>{const b=e.target.closest('[data-say]');if(b)talk(b.dataset.say)};$('#talk-form').onsubmit=e=>{e.preventDefault();const m=$('#message').value;$('#message').value='';talk(m)};$('#reset').onclick=()=>{state=createState();renderUI();notify('序章已重新开始')};$('#mobile-action').onclick=act;document.querySelectorAll('[data-move]').forEach(b=>{const map={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'},k=map[b.dataset.move];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k)});for(const ev of ['pointerup','pointercancel'])b.addEventListener(ev,e=>{e.preventDefault();keys.delete(k)})});
async function status(){try{const r=await fetch('/api/status'),d=await r.json();aiReady=d.configured;$('#ai-badge').textContent=aiReady?'DEEPSEEK AI 在线':'剧情模式';$('#ai-badge').classList.toggle('ready',aiReady)}catch{$('#ai-badge').textContent='剧情模式'}}status();renderUI();requestAnimationFrame(frame);
